  "isHard": true,
  "filas": [
    {
      "cuadros": [
        { "index": 0, "tipo": 1, "hp": 3 }
      ]
    },
    {
      "cuadros": [
        { "index": 0, "tipo": 4, "hp": 7 }
      ]
    }
  ]
}
```
